"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["60743"],{26847(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.configuracao.termo_consentimento.remocao_bloqueada_com_versao_promovida","status":409,"titulo":"Termo com ao menos uma vers\xe3o promovida n\xe3o pode ser removido"},"descricao":{"codigo":"uniplus.configuracao.termo_consentimento.remocao_bloqueada_com_versao_promovida","requisitos":[],"oQueAconteceu":["A remo\xe7\xe3o (`DELETE /api/configuracao/admin/termos-consentimento/{id}`) s\xf3 vale para um termo que nunca teve uma vers\xe3o promovida, isto \xe9, que s\xf3 tem rascunho. Uma vers\xe3o promovida \xe9 um registro imut\xe1vel do texto, da base legal e da forma de aceite que foram aprovados, e o termo que a guarda n\xe3o \xe9 removido.","A busca do termo vem antes: com um `{id}` que n\xe3o existe, a resposta \xe9 a de termo n\xe3o encontrado (`uniplus.configuracao.termo_consentimento.nao_encontrado`). Nada \xe9 alterado."],"comoResolver":["O termo com vers\xe3o promovida permanece no cat\xe1logo. Para mudar o que ele diz, edite o rascunho (`PUT /api/configuracao/admin/termos-consentimento/{id}/rascunho`), marque-o como revisado e promova uma nova vers\xe3o; a vers\xe3o anterior continua imut\xe1vel."],"ondeAparece":["Remo\xe7\xe3o de um termo de consentimento"]},"modulo":{"id":"configuracao","nome":"Configura\xe7\xe3o","assunto":"Termo consentimento"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"bac0ecb24f352b6341ba53a00922b6237dd7a678"}}')}}]);